<div class="crpcrm-request-filters"><form method="get"><input type="hidden" name="page" value="crpcrm-staff"><input type="hidden" name="staff_tab" value="issues"><div class="crpcrm-filter-grid"><?php if($can_manage): ?><label>کارمند<select name="user_id"><option value="">همه</option><?php foreach($staff_users as $u): ?><option value="<?php echo esc_attr($u->ID); ?>" <?php selected($filters['user_id'] ?? '',$u->ID); ?>><?php echo esc_html($u->display_name); ?></option><?php endforeach; ?></select></label><?php endif; ?><label>شدت<select name="severity"><option value="">همه</option><?php foreach($severities as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['severity'] ?? '',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>وضعیت<select name="status"><option value="">همه</option><?php foreach($issue_statuses as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['status'] ?? '',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>نیازمند تصمیم<select name="needs_manager_decision"><option value="">همه</option><option value="1" <?php selected($filters['needs_manager_decision'] ?? '','1'); ?>>بله</option><option value="0" <?php selected($filters['needs_manager_decision'] ?? '','0'); ?>>خیر</option></select></label></div><?php submit_button('اعمال فیلتر','secondary','',false); ?></form></div>
